function renderHome(){refreshIdentity();const upcoming=getUpcomingMoments(),box=$('homeUpcomingMoments');if(box){if(upcoming.length)box.innerHTML=upcoming.slice(0,3).map(m=>`<button class="moment-preview" type="button" data-open-moments><span class="moment-preview-mark">${m.player?`<img src="${avatarDataUri(m.player)}" alt="">`:makeBadgeSvg(loadSettings().badge,teamDisplay().abbr)}</span><span><strong>${escapeHtml(m.player?.name||teamDisplay().name)}</strong><small>${escapeHtml(m.title)}</small></span><b>${m.number||'✦'}</b></button>`).join('');else box.innerHTML='<div class="moment-empty"><strong>Your story starts with the next match.</strong><span>First appearances, goals and milestones will surface here automatically.</span></div>';box.querySelectorAll('[data-open-moments]').forEach(b=>b.onclick=()=>{momentsTab='upcoming';renderMomentsPage();showView(views.momentsView)})}const matches=loadMatches().filter(m=>m.status==='completed'||m.fullTime).sort((a,b)=>(b.completedAt||b.createdAt||'').localeCompare(a.completedAt||a.createdAt||''));const sec=$('homeLastMatchSection'),last=$('homeLastMatch');if(sec&&last){sec.classList.toggle('hidden',!matches.length);if(matches.length){const m=matches[0];last.innerHTML=`<button class="last-match-card" data-history-match="${m.id}" type="button"><span><small>${formatDate(m.date)} · ${escapeHtml(m.competition||'Match')}</small><strong>${escapeHtml(m.teamAbbr||teamDisplay().abbr)} <b>${m.ourScore}</b><i>–</i><b>${m.theirScore}</b> ${escapeHtml(m.opponentAbbr||derivedAbbr(m.opponent))}</strong><em>${escapeHtml(m.opponent)}</em></span><b>View match →</b></button>`;last.querySelector('[data-history-match]').onclick=()=>openMatchReport(m.id)}}}
function renderSeasonSummary(){
 const matches=loadMatches().filter(m=>m.status==='completed'||m.fullTime);
 const premium=loadSettings().planPreview==='platinum';
 let wins=0,draws=0,losses=0,gf=0,ga=0;
 matches.forEach(m=>{gf+=m.ourScore||0;ga+=m.theirScore||0;if(m.ourScore>m.theirScore)wins++;else if(m.ourScore<m.theirScore)losses++;else draws++});
 $('seasonSummary').innerHTML=`<div class="stat-card"><strong>${matches.length}</strong><span>Matches recorded</span></div>`+(premium?`<div class="stat-card"><strong>${gf}</strong><span>Team goals</span></div><div class="stat-card"><strong>${wins}</strong><span>Wins</span></div>`:'');
 if(!matches.length){$('playerStatsTable').innerHTML='<p class="muted stats-empty">Complete a match and your football record will appear here.</p>';return}
 const stats=getPlayerStats('All'),top=[...stats.rows].filter(p=>p.goals>0).sort((a,b)=>b.goals-a.goals)[0];
 $('playerStatsTable').innerHTML=`<div class="home-season-snapshot">${top?`<div class="home-top-scorer"><span>${premium?'Season leader':'Top scorer'}</span><strong>${escapeHtml(top.name)} <em>⚽ ${top.goals}</em></strong></div>`:'<p class="muted">No goals recorded yet.</p>'}<button type="button" class="secondary-btn" id="homeStatsBtn">View season stats</button></div>`;
 $('homeStatsBtn')?.addEventListener('click',()=>showView(views.statsView));
}function renderPlayerCards(rows){$('playerStatsTable').innerHTML=`<div class="player-stats-list">${rows.map(p=>`<article class="player-stat-card"><button class="player-stat-head player-stat-toggle" type="button" aria-expanded="false"><div class="player-stat-shirt">${escapeHtml(p.number||'–')}</div><div class="player-stat-identity"><strong>${escapeHtml(p.name)}</strong>${p.position?`<span>${escapeHtml(p.position)}</span>`:''}</div><div class="player-stat-mini"><span><strong>${p.apps}</strong> Apps</span><span><strong>${p.starts}</strong> Starts</span><span class="mini-goal"><strong>${p.goals}</strong> Goals</span><span class="mini-assist"><strong>${p.assists}</strong> Assists</span></div><span class="player-stat-chevron">⌄</span></button><div class="player-stat-details" hidden><div class="player-stat-grid"><div><strong>${p.apps}</strong><span>Apps</span></div><div><strong>${p.starts}</strong><span>Starts</span></div><div><strong>${p.subApps}</strong><span>Subs</span></div><div><strong>${p.minutes}</strong><span>Minutes</span></div><div class="stat-accent-goal"><strong>${p.goals}</strong><span>Goals</span></div><div class="stat-accent-assist"><strong>${p.assists}</strong><span>Assists</span></div></div></div></article>`).join('')}</div>`;document.querySelectorAll('.player-stat-toggle').forEach(btn=>btn.onclick=()=>{const d=btn.closest('.player-stat-card').querySelector('.player-stat-details'),exp=btn.getAttribute('aria-expanded')==='true';btn.setAttribute('aria-expanded',String(!exp));d.hidden=exp;btn.closest('.player-stat-card').classList.toggle('is-expanded',!exp)})}
function getPlayerStats(filter){const matches=loadMatches().filter(m=>(m.status==='completed'||m.fullTime)&& (filter==='All'||(m.competition||'League')===filter));const ps=loadPlayers();const out={};ps.forEach(p=>out[p.id]={id:p.id,name:p.name,number:p.number||'',position:p.position||'',apps:0,starts:0,subApps:0,minutes:0,goals:0,assists:0});for(const m of matches){const starters=new Set(m.starterPlayerIds||[]),participants=new Set(starters);for(const e of m.events||[]){if(e.type==='substitution'&&e.onId)participants.add(e.onId);if(e.type==='players_adjust_our'&&e.playerId)participants.add(e.playerId);if(e.type==='our_goal'&&e.playerId&&e.goalType!=='own_goal'&&out[e.playerId])out[e.playerId].goals++;if(e.type==='our_goal'&&e.assistPlayerId&&e.goalType!=='own_goal'&&out[e.assistPlayerId])out[e.assistPlayerId].assists++}participants.forEach(id=>{if(out[id]){out[id].apps++;if(starters.has(id))out[id].starts++;else out[id].subApps++}});const mins=computeMinutes(m);Object.entries(mins).forEach(([id,s])=>{if(out[id])out[id].minutes+=Math.round(s/60)})}return{rows:Object.values(out).sort((a,b)=>b.goals-a.goals||b.apps-a.apps||(Number(a.number)||999)-(Number(b.number)||999)),matches}}
function computeMinutes(match){const byPeriod={1:0,2:0};if(match.periodDurations){byPeriod[1]=match.periodDurations[1]||0;byPeriod[2]=match.periodDurations[2]||0}else{byPeriod[1]=match.halfTimeScore?((match.period===2?match.halfTimeElapsedSeconds:match.periodElapsedSeconds)||0):(match.periodElapsedSeconds||0);byPeriod[2]=match.period===2?match.periodElapsedSeconds||0:0}const totals={};const events=match.events||[];let active=new Set(match.starterPlayerIds||[]);let currentPeriod=1,last=0;const add=(ids,sec)=>ids.forEach(id=>totals[id]=(totals[id]||0)+Math.max(0,sec));for(const e of events){if(e.period!==currentPeriod){add(active,Math.max(0,byPeriod[currentPeriod]-last));currentPeriod=e.period;last=0}const t=Number(e.seconds??((e.minute||1)-1)*60);add(active,t-last);last=t;if(e.type==='substitution'){if(e.offId)active.delete(e.offId);if(e.onId)active.add(e.onId)}else if(e.type==='players_adjust_our'){if(e.direction==='on')active.add(e.playerId);else active.delete(e.playerId)}}add(active,Math.max(0,byPeriod[currentPeriod]-last));return totals}
function renderMatchHistory(){const matches=loadMatches().filter(m=>m.status==='completed'||m.fullTime).sort((a,b)=>(b.completedAt||b.createdAt||'').localeCompare(a.completedAt||a.createdAt||''));$('matchHistoryList').innerHTML=matches.length?matches.map(m=>`<button class="history-card" type="button" data-history-match="${m.id}"><span class="history-date">${formatDate(m.date)}</span><span class="history-main"><span class="history-opponent">${escapeHtml(m.teamAbbr||teamDisplay().abbr)} ${m.ourScore} - ${m.theirScore} ${escapeHtml(m.opponentAbbr||derivedAbbr(m.opponent))}</span><br><span class="history-result">${m.competition||'League'} · ${escapeHtml(m.opponent)}</span></span><span>›</span></button>`).join(''):'<p class="muted">No completed matches yet.</p>';document.querySelectorAll('[data-history-match]').forEach(b=>b.onclick=()=>openMatchReport(b.dataset.historyMatch))}
function renderMatchesView(){const fx=loadFixtures();$('upcomingMatchesList').innerHTML=fx.length?fx.map(f=>`<div class="history-card"><span class="history-date">${formatDate(f.date)}</span><span class="history-main"><span class="history-opponent">${escapeHtml(teamDisplay().name)} vs ${escapeHtml(f.opponent)}</span><br><span class="history-result">${f.competition||'League'} · ${f.venue==='away'?'Away':'Home'}</span></span></div>`).join(''):'<p class="muted">No upcoming fixtures.</p>';$('matchesResultsList').innerHTML=$('matchHistoryList').innerHTML;document.querySelectorAll('#matchesResultsList [data-history-match]').forEach(b=>b.onclick=()=>openMatchReport(b.dataset.historyMatch))}
let statsDisplayMode='cards',statsSection='overview';
function buildMoments(filter='All'){
 const matches=loadMatches().filter(m=>(m.status==='completed'||m.fullTime)&&(filter==='All'||(m.competition||'League')===filter)).sort((a,b)=>(a.date||'').localeCompare(b.date||''));
 const players=Object.fromEntries(loadPlayers().map(p=>[p.id,p])),moments=[],seenGoal=new Set(),seenAssist=new Set(),seenApp=new Set();let firstWin=false;
 for(const m of matches){
  const participants=new Set(m.starterPlayerIds||[]);
  (m.events||[]).forEach(e=>{if(e.type==='substitution'&&e.onId)participants.add(e.onId);if(e.type==='players_adjust_our'&&e.playerId&&e.direction==='on')participants.add(e.playerId)});
  participants.forEach(id=>{if(!seenApp.has(id)&&players[id]){seenApp.add(id);moments.push({icon:'⭐',title:'First Appearance',who:players[id].name,detail:`Made their first recorded appearance vs ${m.opponent||'the opposition'}`,date:m.date})}});
  if(!firstWin&&(m.ourScore||0)>(m.theirScore||0)){firstWin=true;moments.push({icon:'🏆',title:'First Win',who:teamDisplay().name,detail:`First recorded win: ${m.ourScore}-${m.theirScore} vs ${m.opponent||'the opposition'}`,date:m.date})}
  const goalsByPlayer={};
  for(const e of m.events||[]){
   if(e.type==='our_goal'&&e.playerId&&e.goalType!=='own_goal'&&players[e.playerId]){
    goalsByPlayer[e.playerId]=(goalsByPlayer[e.playerId]||0)+1;
    if(!seenGoal.has(e.playerId)){seenGoal.add(e.playerId);moments.push({icon:'⚽',title:'First Goal',who:players[e.playerId].name,detail:`Scored their first recorded goal vs ${m.opponent||'the opposition'}`,date:m.date})}
   }
   if(e.type==='our_goal'&&e.assistPlayerId&&players[e.assistPlayerId]&&!seenAssist.has(e.assistPlayerId)){seenAssist.add(e.assistPlayerId);moments.push({icon:'🎯',title:'First Assist',who:players[e.assistPlayerId].name,detail:`Recorded their first assist vs ${m.opponent||'the opposition'}`,date:m.date})}
  }
  Object.entries(goalsByPlayer).forEach(([id,n])=>{if(n>=3)moments.push({icon:'🎩',title:n===3?'Hat-trick':`${n}-Goal Match`,who:players[id].name,detail:`Scored ${n} goals vs ${m.opponent||'the opposition'}`,date:m.date})});
 }
 const stats=getPlayerStats(filter),team=getTeamStats(filter);
 stats.rows.forEach(p=>{
  [10,20,25,50,100].forEach(n=>{if(p.apps>=n)moments.push({icon:'👕',title:`${n} Appearances`,who:p.name,detail:`Reached ${n} appearances`,date:''})});
  [10,20,25,50].forEach(n=>{if(p.goals>=n)moments.push({icon:'⚽',title:`${n} Season Goals`,who:p.name,detail:`Reached ${n} goals`,date:''})});
  [10,20,25].forEach(n=>{if(p.assists>=n)moments.push({icon:'🎯',title:`${n} Assists`,who:p.name,detail:`Reached ${n} assists`,date:''})});
 });
 [5,10,20,25,50].forEach(n=>{if(team.won>=n)moments.push({icon:'🏆',title:`${n} Team Wins`,who:teamDisplay().name,detail:`Reached ${n} wins`,date:''})});
 [25,50,100].forEach(n=>{if(team.gf>=n)moments.push({icon:'⚽',title:`${n} Team Goals`,who:teamDisplay().name,detail:`Reached ${n} goals`,date:''})});
 return moments.reverse();
}
function renderStatsView(){const stats=getPlayerStats(statsFilter),team=getTeamStats(statsFilter),s=loadSettings();$('statsUpgradeBtn')?.classList.add('hidden');const header=$('statsView')?.querySelector('.section-heading h2');if(header)header.textContent=statsSection==='players'?'Player Statistics':statsSection==='moments'?'Moments':'Season Statistics';const tabs=`<div class="platinum-stats-tabs"><button data-statsection="overview" class="${statsSection==='overview'?'active':''}">Season</button><button data-statsection="players" class="${statsSection==='players'?'active':''}">Players</button><button data-statsection="moments" class="${statsSection==='moments'?'active':''}">Moments</button></div>`;let body='';if(statsSection==='overview'){body=`<div class="stat-cards premium-stat-grid"><div class="stat-card"><strong>${team.played}</strong><span>Played</span></div><div class="stat-card"><strong>${team.won}</strong><span>Won</span></div><div class="stat-card"><strong>${team.drawn}</strong><span>Drawn</span></div><div class="stat-card"><strong>${team.lost}</strong><span>Lost</span></div><div class="stat-card"><strong>${team.gf}</strong><span>Goals For</span></div><div class="stat-card"><strong>${team.ga}</strong><span>Against</span></div></div><div class="season-insight"><span class="section-label">SEASON STORY</span><strong>${team.played?`${team.gf} goal${team.gf===1?'':'s'} across ${team.played} match${team.played===1?'':'es'}`:'Your season starts with the first whistle.'}</strong><p>${team.played?`${team.won} win${team.won===1?'':'s'} · ${team.drawn} draw${team.drawn===1?'':'s'} · ${team.lost} loss${team.lost===1?'':'es'}. Every result feeds player stats and Moments.`:'Record a match and GrassSTATory will turn the events into a season record.'}</p></div>`}else if(statsSection==='players'){body=`<div class="stat-player-grid">${stats.rows.map(p=>`<article class="stat-player-card"><div class="stat-player-art"><img src="${avatarDataUri(loadPlayers().find(x=>x.id===p.id)||p)}" alt=""></div><div class="stat-player-heading"><span>#${escapeHtml(p.number||'–')} · ${escapeHtml(p.position||'Player')}</span><h3>${escapeHtml(p.name)}</h3></div><div class="stat-player-numbers"><div><b>${p.apps}</b><span>Apps</span></div><div><b>${p.goals}</b><span>Goals</span></div><div><b>${p.assists}</b><span>Assists</span></div><div><b>${p.minutes}</b><span>Mins</span></div></div></article>`).join('')||'<div class="empty-state"><strong>No player statistics yet.</strong><span>Complete a match to begin.</span></div>'}</div>`}else{const moments=buildMoments(statsFilter);body=`<div class="moments-list premium-moments-list">${moments.length?moments.map(m=>`<article class="moment-history-card"><span>✦</span><div><small>${m.date?formatDate(m.date):'SEASON MILESTONE'}</small><h3>${escapeHtml(m.title)}</h3><strong>${escapeHtml(m.who)}</strong><p>${escapeHtml(m.detail)}</p></div></article>`).join(''):'<div class="empty-state"><strong>No Moments yet.</strong><span>They are created automatically from your match data.</span></div>'}</div>`}$('statsViewBody').innerHTML=tabs+body;document.querySelectorAll('[data-statsection]').forEach(b=>b.onclick=()=>{statsSection=b.dataset.statsection;if(statsSection==='moments'){momentsTab='history';renderMomentsPage();showView(views.momentsView)}else renderStatsView()})}
function getTeamStats(filter){const ms=loadMatches().filter(m=>(m.status==='completed'||m.fullTime)&&(filter==='All'||(m.competition||'League')===filter));let won=0,drawn=0,lost=0,gf=0,ga=0;ms.forEach(m=>{gf+=m.ourScore||0;ga+=m.theirScore||0;if(m.ourScore>m.theirScore)won++;else if(m.ourScore<m.theirScore)lost++;else drawn++});return{played:ms.length,won,drawn,lost,gf,ga}}
function setMatchWizardStep(step){document.querySelectorAll('.match-wizard-step').forEach(s=>s.classList.toggle('hidden',Number(s.dataset.matchStep)!==step));const title=$('matchLobbyTitle');if(title)title.textContent=step===1?'New Match':step===2?'Match Details':step===3?'Match Squad':'Starting Team';window.scrollTo({top:0,behavior:'auto'});}
function openMatchSetup(){const ps=loadPlayers(),s=loadSettings();if(ps.length<5){alert('Add at least 5 players first.');return}window._matchFormat=Number(s.matchFormat)||7;window._available=new Set(ps.map(p=>p.id));window._starters=new Set(lastStartingIds(window._matchFormat));$('matchDate').value=new Date().toISOString().slice(0,10);$('opponentName').value='';$('opponentAbbr').value='';if($('matchCompetition'))$('matchCompetition').value='League';$('matchSetupError').textContent='';document.querySelectorAll('[data-match-format]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.matchFormat)===window._matchFormat));renderOpponentPreview();renderMatchSelection();showView(views.matchSetupView);setMatchWizardStep(1);renderMilestoneWatch()}
function lastStartingIds(n=Number(loadSettings().matchFormat)||7){const ps=new Set(loadPlayers().map(p=>p.id));const last=loadMatches().filter(m=>m.status==='completed'||m.fullTime).sort((a,b)=>(b.completedAt||b.createdAt||'').localeCompare(a.completedAt||a.createdAt||''))[0];const ids=(last?.starterPlayerIds||[]).filter(id=>ps.has(id));return ids.length===n?ids:loadPlayers().slice(0,n).map(p=>p.id)}
function renderMatchSelection(){const ps=loadPlayers(),n=Number(window._matchFormat)||7;$('lobbyFormatText').textContent=`${n}v${n}`;$('startingTeamHeading').textContent=`Starting ${n}`;$('availableCount').textContent=`${window._available.size} selected`;$('starterCount').textContent=`${window._starters.size} / ${n}`;$('availabilityList').innerHTML=ps.map(p=>playerTileMarkup(p,window._available.has(p.id),'availability-tile')).join('');$('starterList').innerHTML=ps.filter(p=>window._available.has(p.id)).map(p=>playerTileMarkup(p,window._starters.has(p.id),'starter-tile')).join('');$('substituteList').innerHTML=ps.filter(p=>window._available.has(p.id)&&!window._starters.has(p.id)).map(p=>`<div class="bench-player"><img src="${avatarDataUri(p)}" alt=""><span><strong>${escapeHtml(p.name)}</strong><small>#${escapeHtml(p.number||'–')} · ${escapeHtml(p.position||'Player')}</small></span></div>`).join('')||'<p class="muted">No substitutes.</p>';document.querySelectorAll('#availabilityList .player-tile').forEach(c=>c.onclick=e=>{e.preventDefault();const id=c.querySelector('input').dataset.id;if(window._available.has(id)){window._available.delete(id);window._starters.delete(id)}else window._available.add(id);renderMatchSelection()});document.querySelectorAll('#starterList .player-tile').forEach(c=>c.onclick=e=>{e.preventDefault();const id=c.querySelector('input').dataset.id;if(window._starters.has(id))window._starters.delete(id);else if(window._starters.size<n)window._starters.add(id);else{flashEvent(`Select exactly ${n} starters`);return}renderMatchSelection()})}
function renderOpponentPreview(){const name=$('opponentName')?.value.trim()||'Opponent',abbr=cleanAbbr($('opponentAbbr')?.value,derivedAbbr(name,'OPP')),cfg={shape:$('opponentBadgeShape')?.value||'shield',symbol:$('opponentBadgeSymbol')?.value||'ball',primary:$('opponentPrimaryColor')?.value||'#2255aa',secondary:$('opponentSecondaryColor')?.value||'#f2f5f7',accent:'#ffffff',upload:''},kit={pattern:$('opponentKitPattern')?.value||'plain',primary:cfg.primary,secondary:cfg.secondary,accent:'#ffffff',collar:'crew'};setCrest($('setupOpponentCrest'),cfg,abbr);if($('setupOpponentKit'))$('setupOpponentKit').innerHTML=makeKitFallbackSvg(kit,cfg,abbr,false);if($('setupOpponentPreviewName'))$('setupOpponentPreviewName').textContent=name}
function currentMatch(){return loadMatches().find(m=>m.id===activeMatchId)||null}
function saveCurrent(m){const ms=loadMatches(),i=ms.findIndex(x=>x.id===m.id);if(i>=0){ms[i]=m;saveMatches(ms)}}
function ensureMatch(m){if(!Array.isArray(m.events))m.events=[];if(!Array.isArray(m.currentOnPitch))m.currentOnPitch=[...(m.starterPlayerIds||[])];if(!Array.isArray(m.currentSubs))m.currentSubs=[...(m.substitutePlayerIds||[])];if(!m.period)m.period=1;if(typeof m.halfTime!=='boolean')m.halfTime=false;if(typeof m.fullTime!=='boolean')m.fullTime=m.status==='completed';if(typeof m.periodElapsedSeconds!=='number')m.periodElapsedSeconds=0;if(!m.periodDurations)m.periodDurations={};if(typeof m.opponentPlayersOnPitch!=='number')m.opponentPlayersOnPitch=Number(m.matchFormat)||loadSettings().playersOnPitch;if(!m.competition)m.competition='League';return m}
function openLive(id){activeMatchId=id;const m=ensureMatch(currentMatch());m.periodStartedAt=null;saveCurrent(m);renderLive();showView(views.liveMatchView)}
function elapsedNow(){const m=currentMatch();if(!m)return 0;return(m.periodElapsedSeconds||0)+(m.periodStartedAt?Math.floor((Date.now()-m.periodStartedAt)/1000):0)}
function matchMinute(){return Math.floor(elapsedNow()/60)+1}
function updateClock(){const m=currentMatch();if(!$('matchClock')||!m)return;$('matchClock').textContent=`${String(Math.floor(elapsedNow()/60)).padStart(2,'0')}:${String(elapsedNow()%60).padStart(2,'0')}`;$('clockStatus').textContent=m.periodStartedAt?'Running':'Paused'}
function startTimer(){const m=currentMatch();if(!m||m.fullTime||m.halfTime||m.periodStartedAt)return;m.periodStartedAt=Date.now();saveCurrent(m);stopTimer();timerInterval=setInterval(updateClock,250);renderLive()}
function pauseTimer(){const m=currentMatch();if(!m||!m.periodStartedAt)return;m.periodElapsedSeconds=elapsedNow();m.periodStartedAt=null;saveCurrent(m);stopTimer();updateClock()}
function stopTimer(){if(timerInterval){clearInterval(timerInterval);timerInterval=null}}
