function saveAdjust(){const m=currentMatch();if(!m)return;const before=eventState(m),sec=elapsedNow(),min=matchMinute(),old=new Set(m.currentOnPitch),next=new Set(adjustOurIds);for(const id of next)if(!old.has(id))m.events.push({id:makeId(),type:'players_adjust_our',period:m.period,seconds:sec,minute:min,playerId:id,direction:'on',newCount:next.size,beforeState:before});for(const id of old)if(!next.has(id))m.events.push({id:makeId(),type:'players_adjust_our',period:m.period,seconds:sec,minute:min,playerId:id,direction:'off',newCount:next.size,beforeState:before});if(m.opponentPlayersOnPitch!==adjustOpponentCount)m.events.push({id:makeId(),type:'players_adjust_opponent',period:m.period,seconds:sec,minute:min,newCount:adjustOpponentCount,beforeState:before});m.currentOnPitch=[...next];m.currentSubs=loadPlayers().map(p=>p.id).filter(id=>m.availablePlayerIds.includes(id)&&!next.has(id));m.opponentPlayersOnPitch=adjustOpponentCount;saveCurrent(m);$('adjustPlayersDialog').close();renderLive()}
