function halfTime(){const m=currentMatch();if(!m||m.period!==1||m.fullTime)return;pauseTimer();m.halfTime=true;m.periodDurations[1]=m.periodElapsedSeconds;m.halfTimeElapsedSeconds=m.periodElapsedSeconds;m.halfTimeScore={our:m.ourScore,their:m.theirScore};saveCurrent(m);renderLive()}
function startSecond(){const m=currentMatch();if(!m||!m.halfTime||m.fullTime)return;m.period=2;m.halfTime=false;m.periodElapsedSeconds=0;m.periodStartedAt=null;saveCurrent(m);renderLive();startTimer()}
