function openMatchReport(id){const m=loadMatches().find(x=>x.id===id);if(!m)return;window._report=m;currentMatchReport=m;$('reportOurName').textContent=m.teamName||teamDisplay().name;$('reportOpponent').textContent=m.opponent;setCrest($('reportOurCrest'),loadSettings().badge,cleanAbbr(m.teamAbbr,teamDisplay().abbr));setCrest($('reportOpponentCrest'),m.opponentIdentity?.badge||{shape:'shield',symbol:'ball',primary:'#2255aa',secondary:'#f2f5f7',accent:'#fff'},cleanAbbr(m.opponentAbbr,derivedAbbr(m.opponent)));$('reportMeta').textContent=`${formatDate(m.date)} · ${m.venue==='home'?'Home':'Away'}`;$('reportCompetition').textContent=m.competition||'League';$('reportOurScore').textContent=m.ourScore;$('reportTheirScore').textContent=m.theirScore;$('reportHalfScore').textContent=`${m.halfTimeScore?.our??0} - ${m.halfTimeScore?.their??0}`;const goals=(m.events||[]).filter(e=>e.type==='our_goal'||e.type==='their_goal');const premium=loadSettings().planPreview==='platinum';$('reportOurScorers').innerHTML=scorerSummary(m,'our_goal',premium);$('reportTheirScorers').innerHTML=scorerSummary(m,'their_goal',premium);const assists=goals.filter(e=>e.type==='our_goal'&&e.assistPlayerId&&e.goalType!=='own_goal').map(e=>{const p=loadPlayers().find(x=>x.id===e.assistPlayerId);return p?`${p.name} (${periodLabel(e.period)} ${e.minute}')`:''}).filter(Boolean);$('reportAssistSummary').classList.toggle('hidden',!assists.length);if(assists.length)$('reportAssistSummary').innerHTML=`<strong>Assists</strong> · ${escapeHtml(assists.join(', '))}`;$('reportGoals').innerHTML=goals.map(e=>`<div class="event-row"><span class="event-minute">${periodLabel(e.period)} ${e.minute}'</span><span>${escapeHtml(eventText(e))}</span></div>`).join('')||'<p class="muted">No goals recorded.</p>';const other=(m.events||[]).filter(e=>e.type==='substitution'||e.type==='players_adjust_our'||e.type==='players_adjust_opponent');$('reportSubs').innerHTML=other.map(e=>`<div class="event-row"><span class="event-minute">${periodLabel(e.period)} ${e.minute}'</span><span>${escapeHtml(eventText(e))}</span></div>`).join('')||'<p class="muted">No player changes recorded.</p>';$('reportStarters').innerHTML=(m.starterPlayerIds||[]).map(id=>loadPlayers().find(p=>p.id===id)).filter(Boolean).map(p=>`<div class="summary-row">${escapeHtml(playerLabel(p))}</div>`).join('')||'<p class="muted">No starters recorded.</p>';$('reportSubstitutes').innerHTML=(m.substitutePlayerIds||[]).map(id=>loadPlayers().find(p=>p.id===id)).filter(Boolean).map(p=>`<div class="summary-row">${escapeHtml(playerLabel(p))}</div>`).join('')||'<p class="muted">No substitutes recorded.</p>';const premiumReport=loadSettings().planPreview==='platinum';$('toggleMatchDetailsBtn').classList.toggle('hidden',!premiumReport);$('reportDetailsPanel').classList.toggle('hidden',!premiumReport);$('reportAssistSummary').classList.toggle('hidden',!premiumReport||!assists.length);renderReportMilestones(m);showView(views.matchReportView)}
let currentMatchReport=null;
function scorerSummary(m,type,premium=false){
  const by=Object.fromEntries(loadPlayers().map(p=>[p.id,p]));
  const events=(m.events||[]).filter(e=>e.type===type);
  const groups=[];
  for(const e of events){
    if(e.goalType==='own_goal'){
      const label=type==='our_goal'?'Opposition Own Goal':(e.ownGoalPlayerId&&by[e.ownGoalPlayerId]?`${playerLabel(by[e.ownGoalPlayerId])} own goal`:'Our Own Goal');
      groups.push({name:label,times:[goalTimeLabel(e)]});
      continue;
    }
    const key=type==='their_goal'?'opp':e.playerId;
    let g=groups.find(x=>x.key===key);
    if(!g){g={key,name:type==='their_goal'?m.opponent:(by[e.playerId]?.name||'Unknown'),times:[]};groups.push(g)}
    g.times.push(goalTimeLabel(e));
  }
  return groups.map(g=>`<div class="scorer-group"><strong>${escapeHtml(g.name)}</strong><span>${premium?escapeHtml(g.times.join(' · ')):''}</span></div>`).join('')||'<span class="muted">No goals</span>';
}

function renderMilestoneWatch(){
  const panel=$('milestoneWatchPanel'),list=$('milestoneWatchList');
  if(!panel||!list)return;
  const premium=loadSettings().planPreview==='platinum';
  if(!premium){panel.classList.add('hidden');return}
  const ps=loadPlayers(), available=window._available||new Set(ps.map(p=>p.id)), starters=window._starters||new Set();
  const matches=loadMatches().filter(m=>m.status==='completed'||m.fullTime);
  const goals={}; const apps={}; const assists={};
  ps.forEach(p=>{goals[p.id]=0;apps[p.id]=0;assists[p.id]=0});
  for(const m of matches){
    const participants=new Set(m.starterPlayerIds||[]);
    for(const e of m.events||[]){
      if(e.type==='substitution'&&e.onId)participants.add(e.onId);
      if(e.type==='players_adjust_our'&&e.playerId)participants.add(e.playerId);
      if(e.type==='our_goal'&&e.playerId&&e.goalType!=='own_goal'&&goals[e.playerId]!=null)goals[e.playerId]++;
      if(e.type==='our_goal'&&e.assistPlayerId&&e.goalType!=='own_goal'&&assists[e.assistPlayerId]!=null)assists[e.assistPlayerId]++;
    }
    participants.forEach(id=>{if(apps[id]!=null)apps[id]++});
  }
  const items=[];
  for(const p of ps){
    if(!available.has(p.id))continue;
    if(starters.has(p.id)){
      const next=apps[p.id]+1;
      if(next%10===0)items.push({text:`${p.name} will make their ${next}th appearance if they play today.`,rank:3});
    }else if(apps[p.id]+1===10){items.push({text:`${p.name} will make their 10th appearance if they play today.`,rank:2})}
    if(goals[p.id]>=0 && [10,20,25,50].includes(goals[p.id]+1))items.push({text:`${p.name}'s next goal will be their ${goals[p.id]+1}th goal of the season.`,rank:4});
    if(assists[p.id]>=0 && [10,20,25,50].includes(assists[p.id]+1))items.push({text:`${p.name}'s next assist will be their ${assists[p.id]+1}th of the season.`,rank:2});
  }
  items.sort((a,b)=>b.rank-a.rank);
  const chosen=items.slice(0,5);
  if(!chosen.length){panel.classList.remove('hidden');list.innerHTML='<p class="muted compact">No major milestones are close enough to show today.</p>';return}
  panel.classList.remove('hidden');
  list.innerHTML=chosen.map(x=>`<div class="milestone-row">${escapeHtml(x.text)}</div>`).join('');
}
function renderReportMilestones(m){
  const box=$('reportMilestones'); if(!box)return;
  const premium=loadSettings().planPreview==='platinum'; if(!premium){box.classList.add('hidden');return}
  const ps=loadPlayers(), reached=[];
  const counts={}; ps.forEach(p=>counts[p.id]={g:0,a:0,app:0});
  for(const mm of loadMatches().filter(x=>x.status==='completed'||x.fullTime)){
    const part=new Set(mm.starterPlayerIds||[]);
    for(const e of mm.events||[]){
      if(e.type==='substitution'&&e.onId)part.add(e.onId);
      if(e.type==='players_adjust_our'&&e.playerId)part.add(e.playerId);
      if(e.type==='our_goal'&&e.playerId&&e.goalType!=='own_goal'&&counts[e.playerId])counts[e.playerId].g++;
      if(e.type==='our_goal'&&e.assistPlayerId&&e.goalType!=='own_goal'&&counts[e.assistPlayerId])counts[e.assistPlayerId].a++;
    }
    part.forEach(id=>{if(counts[id])counts[id].app++});
  }
  for(const p of ps){
    const c=counts[p.id]; if(!c)continue;
    if([10,20,25,50].includes(c.g))reached.push(`⚽ ${p.name} has reached ${c.g} season goals.`);
    if([10,20,25,50].includes(c.a))reached.push(`🎯 ${p.name} has reached ${c.a} assists.`);
    if([10,20,25,50].includes(c.app))reached.push(`👕 ${p.name} has reached ${c.app} appearances.`);
  }
  box.classList.toggle('hidden',!reached.length); if(reached.length)box.innerHTML=`<strong>🏆 Milestones</strong><div>${reached.slice(-4).map(escapeHtml).map(x=>`<div>${x}</div>`).join('')}</div>`;
}
function onboardingSettingsDraft(){const s=loadSettings();return {...s,teamName:$('onboardingTeamName')?.value.trim()||s.teamName,teamAbbr:cleanAbbr($('onboardingTeamAbbr')?.value,s.teamAbbr),ageGroup:$('onboardingAgeGroup')?.value||s.ageGroup,season:$('onboardingSeason')?.value.trim()||s.season,userRole:$('onboardingRole')?.value||s.userRole}}
function setOnboardingStep(step){['onboardingStep1','onboardingStep2','onboardingStep3','onboardingStep4','onboardingDone'].forEach(id=>$(id)?.classList.add('hidden'));const target=step===5?'onboardingDone':`onboardingStep${step}`;$(target)?.classList.remove('hidden');if($('onboardingStepLabel'))$('onboardingStepLabel').textContent=step===5?'READY':`${step} of 4`;window.scrollTo({top:0,behavior:'auto'});if(step===2)renderBadgeStudio();if(step===3)setTimeout(initKitStudio,40);if(step===4)renderPlayerStudio()}
function renderBadgeStudio(){const s=loadSettings(),b=s.badge;if($('badgePreviewMount'))$('badgePreviewMount').innerHTML=makeBadgeSvg(b,cleanAbbr($('onboardingTeamAbbr')?.value,s.teamAbbr));if($('badgeClubNamePreview'))$('badgeClubNamePreview').textContent=$('onboardingTeamName')?.value.trim()||s.teamName;$('badgeShapeGrid').innerHTML=BADGE_SHAPES.map(shape=>`<button type="button" class="badge-option ${shape===b.shape?'selected':''}" data-badge-shape="${shape}"><span>${makeBadgeSvg({...b,shape,upload:''},'')}</span><small>${shape}</small></button>`).join('');$('badgeSymbolGrid').innerHTML=BADGE_SYMBOLS.map(sym=>`<button type="button" class="symbol-option ${sym===b.symbol?'selected':''}" data-badge-symbol="${sym}"><span>${makeBadgeSvg({...b,symbol:sym,upload:''},'')}</span><small>${sym==='monogram'?'Initials':sym}</small></button>`).join('');$('badgePrimaryColor').value=b.primary;$('badgeSecondaryColor').value=b.secondary;$('badgeAccentColor').value=b.accent;document.querySelectorAll('[data-badge-shape]').forEach(x=>x.onclick=()=>{const q=loadSettings();q.badge={...q.badge,shape:x.dataset.badgeShape,upload:''};saveSettings(q);renderBadgeStudio()});document.querySelectorAll('[data-badge-symbol]').forEach(x=>x.onclick=()=>{const q=loadSettings();q.badge={...q.badge,symbol:x.dataset.badgeSymbol,upload:''};saveSettings(q);renderBadgeStudio()})}
function updateBadgeColour(){const s=loadSettings();s.badge={...s.badge,primary:$('badgePrimaryColor').value,secondary:$('badgeSecondaryColor').value,accent:$('badgeAccentColor').value,upload:''};saveSettings(s);renderBadgeStudio()}
function setKitMode(mode){onboardingKitMode=mode;kitFallbackBack=false;document.querySelectorAll('.kit-mode').forEach(b=>b.classList.toggle('active',b.dataset.kit===mode));const s=loadSettings(),k=s.kits[mode];$('kitPrimaryColor').value=k.primary;$('kitSecondaryColor').value=k.secondary;$('kitAccentColor').value=k.accent;renderKitControls();updateKitPreview()}
function renderKitControls(){const s=loadSettings(),k=s.kits[onboardingKitMode];$('kitPatternGrid').innerHTML=KIT_PATTERNS.map(pt=>`<button type="button" class="pattern-option ${pt===k.pattern?'selected':''}" data-kit-pattern="${pt}"><span class="pattern-swatch pattern-${pt}" style="--p:${k.primary};--s:${k.secondary}"></span><small>${pt}</small></button>`).join('');document.querySelectorAll('[data-kit-pattern]').forEach(b=>b.onclick=()=>{const q=loadSettings();q.kits[onboardingKitMode]={...q.kits[onboardingKitMode],pattern:b.dataset.kitPattern,designed:true};saveSettings(q);renderKitControls();updateKitPreview()});document.querySelectorAll('[data-collar]').forEach(b=>b.classList.toggle('active',b.dataset.collar===k.collar));if($('homeKitStatus'))$('homeKitStatus').textContent=s.kits.home.designed?'● Home ready':'○ Home to design';if($('awayKitStatus'))$('awayKitStatus').textContent=s.kits.away.designed?'● Away ready':'○ Away to design'}
function initKitStudio(){const canvas=$('kitCanvas');if(!canvas)return;setKitMode(onboardingKitMode);if(!kitRenderer&&window.GrassKit3D){try{kitRenderer=new GrassKit3D.KitRenderer(canvas,{badgeSvg:makeBadgeSvg(loadSettings().badge,teamDisplay().abbr),config:loadSettings().kits[onboardingKitMode],name:'PLAYER',number:'10'});$('kitFallback').classList.add('webgl-active');$('kitRenderStatus').textContent='Live 3D · drag to rotate'}catch(e){console.warn('3D preview fallback',e);$('kitRenderStatus').textContent='Interactive preview'}}}
function updateKitPreview(){const s=loadSettings(),k=s.kits[onboardingKitMode];$('kitFallback').innerHTML=makeKitFallbackSvg(k,undefined,undefined,kitFallbackBack);document.querySelectorAll('.kit-view-btn').forEach(b=>b.classList.toggle('active',(b.id==='kitBackBtn')===kitFallbackBack));if(kitRenderer){kitRenderer.setConfig(k);kitRenderer.setBadgeSvg(makeBadgeSvg(s.badge,teamDisplay().abbr));kitRenderer.setBack('PLAYER','10')}renderKitControls()}
function updateKitColours(){const s=loadSettings();s.kits[onboardingKitMode]={...s.kits[onboardingKitMode],primary:$('kitPrimaryColor').value,secondary:$('kitSecondaryColor').value,accent:$('kitAccentColor').value,designed:true};saveSettings(s);updateKitPreview()}
function renderPlayerStudio(){const s=loadSettings(),av=AVATAR_OPTIONS.find(a=>a.id===selectedAvatarId)||AVATAR_OPTIONS[0];document.querySelectorAll('.gender-option').forEach(b=>b.classList.toggle('active',b.dataset.gender===avatarGender));$('avatarChoiceGrid').innerHTML=AVATAR_OPTIONS.filter(a=>a.gender===avatarGender).map(a=>`<button type="button" class="avatar-choice ${a.id===selectedAvatarId?'selected':''}" data-avatar-id="${a.id}"><img src="${avatarDataUri({avatarId:a.id,number:$('quickPlayerNumber')?.value||'',name:'',position:''})}" alt=""><span>${a.label}</span></button>`).join('');document.querySelectorAll('[data-avatar-id]').forEach(b=>b.onclick=()=>{selectedAvatarId=b.dataset.avatarId;renderPlayerStudio()});const p={avatarId:selectedAvatarId,name:$('quickPlayerName')?.value||'New player',number:$('quickPlayerNumber')?.value||'',position:$('quickPlayerPosition')?.value||''};$('playerAvatarPreview').innerHTML=`<img src="${avatarDataUri(p)}" alt="">`;$('playerPreviewName').textContent=p.name||'New player';$('playerPreviewMeta').textContent=`${p.number?`#${p.number} · `:''}${p.position||'Position'}`;renderOnboardingSquad()}
function renderOnboardingSquad(){const ps=loadPlayers();if($('onboardingSquadCount'))$('onboardingSquadCount').textContent=`${ps.length} player${ps.length===1?'':'s'}`;if($('onboardingPlayerList'))$('onboardingPlayerList').innerHTML=ps.length?[...ps].sort((a,b)=>(Number(a.number)||999)-(Number(b.number)||999)).map(p=>`<article class="squad-player-card"><img src="${avatarDataUri(p)}" alt=""><div><strong>${escapeHtml(p.name)}</strong><span>#${escapeHtml(p.number||'–')} · ${escapeHtml(p.position||'Player')}</span></div><button type="button" class="mini-delete-player" data-id="${p.id}" aria-label="Remove ${escapeHtml(p.name)}">×</button></article>`).join(''):'<div class="empty-state"><strong>Your squad will appear here.</strong><span>Add players above. Their identity is reused throughout the app.</span></div>';document.querySelectorAll('.mini-delete-player').forEach(btn=>btn.onclick=()=>{savePlayers(loadPlayers().filter(p=>p.id!==btn.dataset.id));renderOnboardingSquad()});const ready=ps.length>=5;if($('finishOnboardingBtn'))$('finishOnboardingBtn').disabled=!ready;if($('onboardingSquadHint'))$('onboardingSquadHint').textContent=ready?`${ps.length} players added. You can finish setup or keep building.`:'Add at least 5 players to continue.'}
function renderOnboarding(){const s=loadSettings();if($('onboardingTeamName'))$('onboardingTeamName').value=s.teamName==='Your Team'?'':s.teamName;if($('onboardingTeamAbbr'))$('onboardingTeamAbbr').value=s.teamAbbr==='YTM'?'':cleanAbbr(s.teamAbbr,'YTM');if($('onboardingAgeGroup'))$('onboardingAgeGroup').value=s.ageGroup||'';if($('onboardingSeason'))$('onboardingSeason').value=s.season||'2026/27';if($('onboardingRole'))$('onboardingRole').value=s.userRole||'Parent';renderBadgeStudio();renderOnboardingSquad()}
function openOnboarding(start=1){renderOnboarding();setOnboardingStep(start);showView(views.onboardingView);if(start===1)setTimeout(()=>$('onboardingTeamName')?.focus(),80)}
function finishOnboardingV21(){const s=loadSettings();saveSettings({...s,onboardingComplete:true,planPreview:'platinum',primaryColor:s.kits.home.primary,secondaryColor:s.kits.home.secondary,matchFormat:Number(s.matchFormat)||7,playersOnPitch:Number(s.matchFormat)||7});$('onboardingCompleteTitle').textContent=`${loadSettings().teamName} is ready.`;$('onboardingCompleteMeta').textContent=`Home & away kits · ${loadPlayers().length} players · Premium active`;setOnboardingStep(5)}
function renderMomentsPage(){const upcoming=getUpcomingMoments(),history=buildMoments('All');document.querySelectorAll('[data-moment-tab]').forEach(b=>b.classList.toggle('active',b.dataset.momentTab===momentsTab));$('momentsPageBody').innerHTML=momentsTab==='upcoming'?`<div class="moments-list premium-moments-list">${upcoming.length?upcoming.map(m=>`<article class="moment-history-card upcoming"><span>${m.number||'✦'}</span><div><small>COULD HAPPEN NEXT</small><h3>${escapeHtml(m.title)}</h3><strong>${escapeHtml(m.player?.name||teamDisplay().name)}</strong><p>${escapeHtml(m.detail)}</p></div></article>`).join(''):'<div class="empty-state"><strong>No milestone is within two events yet.</strong><span>Keep recording matches and this list will update automatically.</span></div>'}</div>`:`<div class="moments-list premium-moments-list">${history.length?history.map(m=>`<article class="moment-history-card"><span>✦</span><div><small>${m.date?formatDate(m.date):'SEASON MILESTONE'}</small><h3>${escapeHtml(m.title)}</h3><strong>${escapeHtml(m.who)}</strong><p>${escapeHtml(m.detail)}</p></div></article>`).join(''):'<div class="empty-state"><strong>Your history will build here.</strong><span>First goals, appearances, hat-tricks and club milestones are created automatically.</span></div>'}</div>`}
function wire(){
  $('newMatchBtn')?.addEventListener('click',()=>{if(!loadSettings().onboardingComplete){openOnboarding();return}openMatchSetup()});
  $('settingsBtn')?.addEventListener('click',()=>showView(views.settingsView));$('settingsBackBtn')?.addEventListener('click',()=>showView(views.homeView));$('matchesNewBtn')?.addEventListener('click',openMatchSetup);
  $('homePlayerStatsBtn')?.addEventListener('click',()=>{statsSection='players';showView(views.statsView);renderStatsView()});$('homeSeasonStatsBtn')?.addEventListener('click',()=>{statsSection='overview';showView(views.statsView);renderStatsView()});$('homeMomentsBtn')?.addEventListener('click',()=>{momentsTab='upcoming';renderMomentsPage();showView(views.momentsView)});$('homeMomentsSeeAll')?.addEventListener('click',()=>{momentsTab='upcoming';renderMomentsPage();showView(views.momentsView)});$('momentsBackBtn')?.addEventListener('click',()=>showView(views.homeView));document.querySelectorAll('[data-moment-tab]').forEach(b=>b.addEventListener('click',()=>{momentsTab=b.dataset.momentTab;renderMomentsPage()}));
  $('editIdentityStudioBtn')?.addEventListener('click',()=>openOnboarding(2));$('resetPrototypeBtn')?.addEventListener('click',()=>{if(confirm('Reset GrassSTATory on this device? This deletes the club, squad, matches, statistics and Moments.')){localStorage.removeItem(PLAYER_STORAGE_KEY);localStorage.removeItem(SETTINGS_STORAGE_KEY);localStorage.removeItem(MATCH_STORAGE_KEY);localStorage.removeItem(UPCOMING_STORAGE_KEY);location.reload()}});
  $('onboardingNext1')?.addEventListener('click',()=>{const name=$('onboardingTeamName').value.trim();if(!name){flashEvent('ENTER A CLUB NAME');return}const s=loadSettings();saveSettings({...s,teamName:name,teamAbbr:cleanAbbr($('onboardingTeamAbbr').value,derivedAbbr(name,'CLB')),ageGroup:$('onboardingAgeGroup').value,season:$('onboardingSeason').value.trim()||'2026/27',userRole:$('onboardingRole').value});setOnboardingStep(2)});$('onboardingBack2')?.addEventListener('click',()=>setOnboardingStep(1));$('onboardingNext2')?.addEventListener('click',()=>setOnboardingStep(3));$('onboardingBack3')?.addEventListener('click',()=>setOnboardingStep(2));$('onboardingNext3')?.addEventListener('click',()=>{if(!loadSettings().kits.away.designed){setKitMode('away');flashEvent('DESIGN YOUR AWAY KIT');return}setOnboardingStep(4)});$('onboardingBack4')?.addEventListener('click',()=>setOnboardingStep(3));$('finishOnboardingBtn')?.addEventListener('click',finishOnboardingV21);$('onboardingGoHomeBtn')?.addEventListener('click',()=>{closeOnboarding();showView(views.homeView)});
  ['badgePrimaryColor','badgeSecondaryColor','badgeAccentColor'].forEach(id=>$(id)?.addEventListener('input',updateBadgeColour));$('badgeUploadInput')?.addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>900000){alert('Please use a badge image under 900KB for this prototype.');return}const r=new FileReader();r.onload=()=>{const s=loadSettings();s.badge={...s.badge,upload:String(r.result)};saveSettings(s);renderBadgeStudio()};r.readAsDataURL(f)});
  document.querySelectorAll('.kit-mode').forEach(b=>b.addEventListener('click',()=>setKitMode(b.dataset.kit)));['kitPrimaryColor','kitSecondaryColor','kitAccentColor'].forEach(id=>$(id)?.addEventListener('input',updateKitColours));document.querySelectorAll('[data-collar]').forEach(b=>b.addEventListener('click',()=>{const s=loadSettings();s.kits[onboardingKitMode]={...s.kits[onboardingKitMode],collar:b.dataset.collar,designed:true};saveSettings(s);renderKitControls();updateKitPreview()}));$('copyHomeToAwayBtn')?.addEventListener('click',()=>{const s=loadSettings();s.kits.away={...s.kits.home,primary:s.kits.away.primary,secondary:s.kits.away.secondary,designed:true};saveSettings(s);setKitMode('away');flashEvent('HOME DESIGN COPIED')});$('kitFrontBtn')?.addEventListener('click',()=>{kitFallbackBack=false;updateKitPreview();kitRenderer?.front()});$('kitBackBtn')?.addEventListener('click',()=>{kitFallbackBack=true;updateKitPreview();kitRenderer?.back()});$('kitResetViewBtn')?.addEventListener('click',()=>{kitFallbackBack=false;updateKitPreview();kitRenderer?.setRotation(0)});
  document.querySelectorAll('.gender-option').forEach(b=>b.addEventListener('click',()=>{avatarGender=b.dataset.gender;const first=AVATAR_OPTIONS.find(a=>a.gender===avatarGender);if(first)selectedAvatarId=first.id;renderPlayerStudio()}));['quickPlayerName','quickPlayerNumber'].forEach(id=>$(id)?.addEventListener('input',renderPlayerStudio));$('quickPlayerPosition')?.addEventListener('change',renderPlayerStudio);$('quickAddPlayerBtn')?.addEventListener('click',()=>{const name=$('quickPlayerName').value.trim();if(!name){flashEvent('ENTER PLAYER NAME');return}const ps=loadPlayers();ps.push({id:makeId(),name,number:$('quickPlayerNumber').value.trim(),position:$('quickPlayerPosition').value,avatarId:selectedAvatarId,gender:avatarGender});savePlayers(ps);$('quickPlayerName').value='';$('quickPlayerNumber').value='';$('quickPlayerPosition').value='';renderPlayerStudio();flashEvent('PLAYER ADDED')});
  $('cancelMatchSetupBtn')?.addEventListener('click',()=>showView(views.homeView));document.querySelectorAll('[data-match-next]').forEach(btn=>btn.addEventListener('click',()=>{const n=Number(btn.dataset.matchNext);if(n===2&&!$('opponentName').value.trim()){flashEvent('ENTER OPPONENT');return}setMatchWizardStep(n)}));document.querySelectorAll('[data-match-back]').forEach(btn=>btn.addEventListener('click',()=>setMatchWizardStep(Number(btn.dataset.matchBack))));document.querySelectorAll('[data-match-format]').forEach(b=>b.addEventListener('click',()=>{window._matchFormat=Number(b.dataset.matchFormat);document.querySelectorAll('[data-match-format]').forEach(x=>x.classList.toggle('selected',x===b));window._starters=new Set([...window._starters].slice(0,window._matchFormat));renderMatchSelection()}));['opponentName','opponentAbbr','opponentPrimaryColor','opponentSecondaryColor','opponentKitPattern','opponentBadgeShape','opponentBadgeSymbol'].forEach(id=>{$(id)?.addEventListener('input',renderOpponentPreview);$(id)?.addEventListener('change',renderOpponentPreview)});
  $('matchSetupForm')?.addEventListener('submit',e=>{e.preventDefault();const s=loadSettings(),available=[...(window._available||new Set())],starters=[...(window._starters||new Set())],n=Number(window._matchFormat)||7,opponent=$('opponentName').value.trim();if(!opponent){setMatchWizardStep(1);flashEvent('ENTER OPPONENT');return}if(starters.length!==n){$('matchSetupError').textContent=`Select exactly ${n} starters.`;flashEvent(`SELECT ${n} STARTERS`);return}const team=teamDisplay(),oppAbbr=cleanAbbr($('opponentAbbr').value,derivedAbbr(opponent));const oppBadge={shape:$('opponentBadgeShape')?.value||'shield',symbol:$('opponentBadgeSymbol')?.value||'ball',primary:$('opponentPrimaryColor').value,secondary:$('opponentSecondaryColor').value,accent:'#ffffff',upload:''};const m={id:makeId(),teamName:team.name,teamAbbr:team.abbr,opponent,opponentAbbr:oppAbbr,opponentIdentity:{badge:oppBadge,kit:{pattern:$('opponentKitPattern').value,primary:$('opponentPrimaryColor').value,secondary:$('opponentSecondaryColor').value}},matchFormat:n,date:$('matchDate').value,venue:document.querySelector('input[name="venue"]:checked')?.value||'home',competition:$('matchCompetition').value,availablePlayerIds:available,starterPlayerIds:starters,substitutePlayerIds:available.filter(id=>!starters.includes(id)),currentOnPitch:starters,currentSubs:available.filter(id=>!starters.includes(id)),opponentPlayersOnPitch:n,status:'live',period:1,halfTime:false,fullTime:false,periodElapsedSeconds:0,periodStartedAt:null,periodDurations:{},ourScore:0,theirScore:0,events:[],createdAt:new Date().toISOString()};saveSettings({...s,matchFormat:n,playersOnPitch:n});saveMatches([...loadMatches(),m]);startTimerForNewMatch(m.id)});
  $('exitLiveMatchBtn')?.addEventListener('click',()=>{pauseTimer();showView(views.homeView)});$('timerBtn')?.addEventListener('click',()=>{const m=currentMatch();if(m?.periodStartedAt)pauseTimer();else startTimer()});$('halfTimeBtn')?.addEventListener('click',halfTime);$('startSecondHalfBtn')?.addEventListener('click',startSecond);$('fullTimeBtn')?.addEventListener('click',fullTime);$('ourGoalBtn')?.addEventListener('click',()=>openGoalDialog('our_goal'));$('theirGoalBtn')?.addEventListener('click',()=>openGoalDialog('their_goal'));$('subBtn')?.addEventListener('click',openSubDialog);$('adjustPlayersBtn')?.addEventListener('click',openAdjust);$('undoBtn')?.addEventListener('click',()=>{undoLast();flashEvent('LAST EVENT UNDONE')});
  document.querySelectorAll('.goal-type').forEach(b=>b.addEventListener('click',()=>{window._goalType=b.dataset.goalType;$('goalType').value=window._goalType;document.querySelectorAll('.goal-type').forEach(x=>x.classList.toggle('active',x===b));$('ownGoalPlayerWrap').classList.toggle('hidden',window._goalType!=='own_goal');if($('goalDialog').dataset.kind==='our_goal')$('goalPlayerSection').classList.toggle('hidden',window._goalType==='own_goal')}));$('saveGoalBtn')?.addEventListener('click',()=>{const kind=$('goalDialog').dataset.kind,gt=window._goalType||'normal',pid=kind==='our_goal'&&gt!=='own_goal'?window._goalScorerId:null,aid=kind==='our_goal'&&gt!=='own_goal'?window._goalAssistId:null,og=$('ownGoalPlayer').value||null;if(kind==='our_goal'&&gt!=='own_goal'&&!pid){flashEvent('CHOOSE A SCORER');return}recordGoal(kind,gt,pid,aid,og);$('goalDialog').close()});$('cancelGoalBtn')?.addEventListener('click',()=>$('goalDialog').close());
  $('subForm')?.addEventListener('submit',e=>{e.preventDefault();saveBatchSubs()});$('saveBatchSubsBtn')?.addEventListener('click',e=>{e.preventDefault();saveBatchSubs()});$('cancelSubBtn')?.addEventListener('click',()=>$('subDialog').close());$('saveAdjustPlayersBtn')?.addEventListener('click',()=>{saveAdjust();flashEvent('MATCH STATE UPDATED')});$('cancelAdjustPlayersBtn')?.addEventListener('click',()=>$('adjustPlayersDialog').close());$('oppCountMinus')?.addEventListener('click',()=>{adjustOpponentCount=Math.max(0,adjustOpponentCount-1);renderAdjust()});$('oppCountPlus')?.addEventListener('click',()=>{adjustOpponentCount=Math.min(20,adjustOpponentCount+1);renderAdjust()});
  $('addPlayerBtn')?.addEventListener('click',()=>openPlayerDialog());$('cancelPlayerBtn')?.addEventListener('click',()=>$('playerDialog').close());$('playerForm')?.addEventListener('submit',e=>{e.preventDefault();const ps=loadPlayers(),data={name:$('playerName').value.trim(),number:$('playerNumber').value.trim(),position:$('playerPosition').value};if(!data.name)return;if(editingPlayerId){const p=ps.find(x=>x.id===editingPlayerId);if(p)Object.assign(p,data)}else ps.push({id:makeId(),...data,avatarId:'m-crop',gender:'male'});savePlayers(ps);$('playerDialog').close();renderPlayers()});$('deletePlayerBtn')?.addEventListener('click',()=>{if(!editingPlayerId)return;savePlayers(loadPlayers().filter(p=>p.id!==editingPlayerId));$('playerDialog').close();renderPlayers()});
  $('settingsForm')?.addEventListener('submit',e=>{e.preventDefault();const s=loadSettings();saveSettings({...s,teamName:$('teamName').value.trim()||s.teamName,teamAbbr:cleanAbbr($('teamAbbr').value,s.teamAbbr),ageGroup:$('ageGroup').value,season:$('season').value.trim()||s.season,matchFormat:Number($('matchFormat').value)||s.matchFormat,playersOnPitch:Number($('matchFormat').value)||s.matchFormat});$('settingsSaved').textContent='Saved';refreshIdentity();renderSettings();setTimeout(()=>$('settingsSaved').textContent='',1200)});$('matchFormat')?.addEventListener('change',()=>{$('playersOnPitch').value=$('matchFormat').value});
  document.querySelectorAll('[data-nav]').forEach(btn=>btn.addEventListener('click',()=>{const n=btn.dataset.nav;document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('is-active',b===btn));const target={home:views.homeView,matches:views.matchesView,stats:views.statsView,team:views.settingsView,settings:views.settingsView}[n]||views.homeView;showView(target);if(n==='stats'){statsSection='overview';renderStatsView()}}));$('statsFilterRow')?.querySelectorAll('[data-stats-filter]').forEach(btn=>btn.addEventListener('click',()=>{statsFilter=btn.dataset.statsFilter;document.querySelectorAll('[data-stats-filter]').forEach(b=>b.classList.toggle('active-filter',b===btn));renderStatsView()}));
  $('toggleMatchDetailsBtn')?.addEventListener('click',()=>{const p=$('reportDetailsPanel');const hidden=p.classList.toggle('hidden');$('toggleMatchDetailsBtn').textContent=hidden?'Match Details':'Hide Details'});$('deleteMatchBtn')?.addEventListener('click',()=>{if(!currentMatchReport)return;if(!confirm('Delete this match from this device? This also removes its statistics and Moments.'))return;saveMatches(loadMatches().filter(m=>m.id!==currentMatchReport.id));currentMatchReport=null;activeMatchId=null;renderHome();showView(views.homeView);flashEvent('MATCH DELETED')});$('reportBackBtn')?.addEventListener('click',()=>showView(views.homeView));$('reportHomeBtn')?.addEventListener('click',openMatchSetup);$('shareResultBtn')?.addEventListener('click',()=>{const m=currentMatchReport;if(!m)return;const text=`${m.teamName} ${m.ourScore}-${m.theirScore} ${m.opponent} · ${m.competition}`;if(navigator.share)navigator.share({title:'GrassSTATory match result',text});else navigator.clipboard?.writeText(text).then(()=>flashEvent('RESULT COPIED'))});$('shareMilestoneWatchBtn')?.addEventListener('click',()=>{const txt=[...document.querySelectorAll('#milestoneWatchList .milestone-row')].map(x=>x.textContent).join('\n');if(navigator.share)navigator.share({title:'GrassSTATory milestone watch',text:txt});else navigator.clipboard?.writeText(txt).then(()=>flashEvent('MOMENTS COPIED'))});$('shareLiveBtn')?.addEventListener('click',()=>{const m=currentMatch();if(!m)return;const text=`Live on GrassSTATory: ${m.teamName} ${m.ourScore}-${m.theirScore} ${m.opponent}`;if(navigator.share)navigator.share({title:'GrassSTATory Live Match',text});else navigator.clipboard?.writeText(text).then(()=>flashEvent('LIVE SCORE COPIED'))});
  $('momentCloseBtn')?.addEventListener('click',()=>$('momentDialog').close());$('momentBackToMatchBtn')?.addEventListener('click',()=>$('momentDialog').close());$('shareMomentBtn')?.addEventListener('click',()=>{const text=`${$('momentPlayerName').textContent} · ${$('momentBigNumber').textContent} ${$('momentTitle').textContent} · ${teamDisplay().name}`;if(navigator.share)navigator.share({title:'GrassSTATory Moment',text});else navigator.clipboard?.writeText(text).then(()=>flashEvent('MOMENT COPIED'))});
}

function closeOnboarding(){$('onboardingView')?.classList.add('hidden')}
function startTimerForNewMatch(id){activeMatchId=id;const m=currentMatch();if(!m)return;showView(views.liveMatchView);startTimer()}

saveSettings({...loadSettings(),planPreview:'platinum'});refreshIdentity();wire();renderHome();renderSettings();if(!loadSettings().onboardingComplete)openOnboarding();

function renderTeamPreview(){
 const box=$('teamPreviewList'),btn=$('addTeamPreviewBtn'); if(!box||!btn)return;
 const s=loadSettings(),teams=loadJson('grassstatory.teamsPreview',[]);
 box.innerHTML=`<div class="summary-row"><strong>${escapeHtml(s.teamName||'Current team')}</strong><span>Current</span></div>`+teams.map(t=>`<div class="summary-row"><strong>${escapeHtml(t.name)}</strong><span>Preview team</span></div>`).join('');
 btn.disabled=s.planPreview!=='platinum'; btn.textContent=s.planPreview==='platinum'?'＋ Add Team':'＋ Add Team 🔒 Platinum';
 btn.onclick=()=>{if(s.planPreview!=='platinum'){showView(views.platinumView);return}const name=prompt('Team name');if(!name)return;teams.push({id:makeId(),name:name.trim()});saveJson('grassstatory.teamsPreview',teams);renderTeamPreview()};
}
